#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")/.."
cmake -S . -B .task-build/lib -DBUILD_SHARED_LIBS=OFF -DBUILD_TESTING=OFF -DBUILD_PROGRAMS=OFF -DBUILD_EXAMPLES=OFF -DENABLE_EXTERNAL_LIBS=OFF -DENABLE_MPEG=OFF -DENABLE_CPACK=OFF -DENABLE_PACKAGE_CONFIG=OFF -DINSTALL_PKGCONFIG_MODULE=OFF -DINSTALL_MANPAGES=OFF -DCMAKE_DISABLE_FIND_PACKAGE_PythonInterp=TRUE -DCMAKE_BUILD_TYPE=Release -DCMAKE_DISABLE_FIND_PACKAGE_Ogg=TRUE -DCMAKE_DISABLE_FIND_PACKAGE_Vorbis=TRUE -DCMAKE_DISABLE_FIND_PACKAGE_FLAC=TRUE -DCMAKE_DISABLE_FIND_PACKAGE_Opus=TRUE -DCMAKE_DISABLE_FIND_PACKAGE_mp3lame=TRUE -DCMAKE_DISABLE_FIND_PACKAGE_mpg123=TRUE -DCMAKE_DISABLE_FIND_PACKAGE_ALSA=TRUE -DCMAKE_DISABLE_FIND_PACKAGE_Sndio=TRUE -DCMAKE_DISABLE_FIND_PACKAGE_Speex=TRUE -DCMAKE_DISABLE_FIND_PACKAGE_SQLite3=TRUE
cmake --build .task-build/lib --target sndfile --parallel 4

cc -std=c99 -O1 -I. -Iinclude -Isrc -I.task-build/lib/src task_support/baseline.c .task-build/lib/libsndfile.a -lm -o .task-build/baseline
